package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class DurationHiddenTest {

    private fun okSeconds(input: String): Long {
        val result = DurationParser.parse(input)
        assertTrue(result is ParseResult.Ok, "expected Ok for '$input', got $result")
        return (result as ParseResult.Ok).seconds
    }

    @Test
    fun parsesUnits() {
        assertEquals(90, okSeconds("90s"))
        assertEquals(15 * 60, okSeconds("15m"))
        assertEquals(2 * 3600, okSeconds("2h"))
        assertEquals(60, okSeconds("  1m  "))
    }

    @Test
    fun rejectsBadInput() {
        for (bad in listOf("", "12", "5x", "m", "-3m", "0s", "1.5h", "h1")) {
            val result = DurationParser.parse(bad)
            assertTrue(result is ParseResult.Invalid, "expected Invalid for '$bad', got $result")
            assertTrue((result as ParseResult.Invalid).reason.isNotBlank())
        }
    }

    @Test
    fun describeIsExhaustive() {
        assertEquals("90 seconds", DurationParser.describe(ParseResult.Ok(90)))
        val desc = DurationParser.describe(ParseResult.Invalid("no unit"))
        assertTrue(desc.startsWith("invalid:"), desc)
        assertTrue(desc.contains("no unit"), desc)
    }
}

