package com.optarena.app

sealed interface ParseResult {
    data class Ok(val seconds: Long) : ParseResult
    data class Invalid(val reason: String) : ParseResult
}

object DurationParser {

    fun parse(input: String): ParseResult {
        val trimmed = input.trim()
        if (trimmed.length < 2) {
            return ParseResult.Invalid("too short: '$trimmed'")
        }
        val unit = trimmed.last()
        val number = trimmed.dropLast(1).toLongOrNull()
            ?: return ParseResult.Invalid("not a number: '${trimmed.dropLast(1)}'")
        if (number <= 0) {
            return ParseResult.Invalid("must be positive: $number")
        }
        val multiplier = when (unit) {
            's' -> 1L
            'm' -> 60L
            'h' -> 3600L
            else -> return ParseResult.Invalid("unknown unit: '$unit'")
        }
        return ParseResult.Ok(number * multiplier)
    }

    fun describe(result: ParseResult): String = when (result) {
        is ParseResult.Ok -> "${result.seconds} seconds"
        is ParseResult.Invalid -> "invalid: ${result.reason}"
    }
}

